// Extrae texto, foto y chat del update de Telegram y calcula fechas de referencia en Córdoba
// (hoy e inicio de semana/mes/año) para que Claude resuelva los períodos de las consultas.
// Comandos (/start, /help) y mensajes sin texto salen con texto vacío; las fotos llevan photo_file_id
// (la de mayor resolución) para que Claude lea el ticket.
const hoy = $now.setZone('America/Argentina/Cordoba');
const f = d => d.toFormat('dd-MM-yyyy');
const DIAS = ['lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado', 'domingo'];
const TIPOS = ['photo', 'voice', 'audio', 'video', 'document', 'sticker', 'location', 'contact'];

const salida = [];
for (const item of $input.all()) {
  const m = item.json.message;
  if (!m || !m.chat) continue;

  const textoCrudo = typeof m.text === 'string' ? m.text.trim() : '';
  const fotos = Array.isArray(m.photo) ? m.photo : [];
  salida.push({
    json: {
      texto: textoCrudo.startsWith('/') ? '' : textoCrudo,
      tipo_mensaje: textoCrudo ? 'text' : (TIPOS.find(t => m[t]) || 'otro'),
      photo_file_id: fotos.length ? fotos[fotos.length - 1].file_id : '',
      caption: typeof m.caption === 'string' ? m.caption.trim() : '',
      chat_id: m.chat.id,
      nombre: (m.from && m.from.first_name) || '',
      message_id: m.message_id,
      fecha_hoy: f(hoy),
      dia_semana: DIAS[hoy.weekday - 1],
      inicio_semana: f(hoy.startOf('week')),
      inicio_mes: f(hoy.startOf('month')),
      inicio_anio: f(hoy.startOf('year')),
    },
  });
}

return salida;

// Limpia la respuesta de Claude (bloques markdown, texto extra) y la parsea de forma segura.
// Si algo no cierra, marca el mensaje como INVALIDO en vez de romper el flujo.
const origen = $('Extraer datos del mensaje').item.json;
const r = $json;

let crudo = '';
if (typeof r.merged_response === 'string') crudo = r.merged_response;
else if (Array.isArray(r.content)) crudo = r.content.filter(c => c && c.type === 'text').map(c => c.text).join('\n');
else if (typeof r.content === 'string') crudo = r.content;
else if (typeof r.text === 'string') crudo = r.text;
else if (typeof r.output === 'string') crudo = r.output;

let limpio = String(crudo).replace(/```(?:json)?/gi, '').trim();
const ini = limpio.indexOf('{');
const fin = limpio.lastIndexOf('}');
if (ini !== -1 && fin > ini) limpio = limpio.slice(ini, fin + 1);

let d = {};
let errorParseo = '';
try {
  d = JSON.parse(limpio);
  if (!d || typeof d !== 'object' || Array.isArray(d)) throw new Error('La respuesta no es un objeto JSON');
} catch (e) {
  d = {};
  errorParseo = e.message;
}

const CATEGORIAS = [
  'Alimentación / Supermercado', 'Salidas / Ocio', 'Servicios y Suscripciones', 'Salud y Deporte',
  'Farmacia', 'Transporte / Vehículo', 'Indumentaria / Compras', 'Vivienda / Hogar', 'Educación / Cursos',
  'Donaciones', 'Ingresos / Sueldo / Extras', 'Otros',
];
// Por si Claude devuelve la categoría con la aclaración entre paréntesis
const limpiarCategoria = s => String(s || '').replace(/\s*\(.*\)\s*$/, '').trim();
const esFecha = s => /^\d{2}-\d{2}-\d{4}$/.test(String(s || ''));

const tipoCrudo = String(d.tipo || '').toUpperCase().trim();
let tipo = ['GASTO', 'INGRESO', 'CONSULTA', 'SALDOS', 'AJUSTE', 'PATRIMONIO', 'PERMITIR', 'PRESUPUESTO'].includes(tipoCrudo) ? tipoCrudo : 'INVALIDO';
const esMovimiento = t => t === 'GASTO' || t === 'INGRESO';
// Tipos que necesitan un monto: movimientos y "¿puedo gastar?" mayor a 0; ajuste y presupuesto pueden ser 0
const conMontoPositivo = t => esMovimiento(t) || t === 'PERMITIR';
const conMontoCero = t => t === 'AJUSTE' || t === 'PRESUPUESTO';

// Acepta número o texto tipo "15.000", "15.000,50" o "$ 2500"
let monto = d.monto;
if (typeof monto === 'string') {
  monto = monto.replace(/[^\d,.-]/g, '').replace(/\.(?=\d{3}(\D|$))/g, '').replace(',', '.');
}
monto = Number(monto);
if (conMontoPositivo(tipo) && !(Number.isFinite(monto) && monto > 0)) tipo = 'INVALIDO';
if (conMontoCero(tipo) && !(Number.isFinite(monto) && monto >= 0 && d.monto !== '' && d.monto != null)) tipo = 'INVALIDO';
monto = conMontoPositivo(tipo) || conMontoCero(tipo) ? Math.round(monto * 100) / 100 : 0;

const monedaCruda = String(d.moneda || '').toUpperCase();
const moneda = monedaCruda.includes('EUR') || monedaCruda.includes('€') ? 'EUR'
  : monedaCruda.includes('USD') ? 'USD' : 'ARS';
const fecha = esFecha(d.fecha) ? d.fecha : origen.fecha_hoy;
const categoriaCruda = limpiarCategoria(d.categoria);
const categoria = CATEGORIAS.includes(categoriaCruda) ? categoriaCruda : 'Otros';
const descripcion = String(d.descripcion || '').trim();
const metodoPago = String(d.metodo_pago || '').trim() || 'No especificado';

const consultaTipo = String(d.consulta_tipo || '').toUpperCase().trim();
const consultaCategoria = limpiarCategoria(d.consulta_categoria);
const consulta = tipo === 'CONSULTA' ? {
  desde: esFecha(d.consulta_desde) ? d.consulta_desde : origen.inicio_mes,
  hasta: esFecha(d.consulta_hasta) ? d.consulta_hasta : origen.fecha_hoy,
  tipo: ['GASTO', 'INGRESO', 'AMBOS'].includes(consultaTipo) ? consultaTipo : 'GASTO',
  categoria: CATEGORIAS.includes(consultaCategoria) ? consultaCategoria : '',
  titulo: String(d.consulta_titulo || '').trim() || 'el período',
} : null;

return {
  json: {
    fecha,
    tipo,
    monto,
    moneda,
    categoria,
    descripcion,
    metodo_pago: metodoPago,
    notas: String(d.notas || '').trim(),
    consulta,
    chat_id: origen.chat_id,
    texto_original: origen.texto || origen.caption,
    error_parseo: errorParseo,
    respuesta_cruda: crudo,
  },
};

// Suma los movimientos de la hoja que caen en el período pedido, separados por moneda
// (no se mezclan ARS, USD y EUR), y arma la respuesta para Telegram.
// Los gastos en pesos se comparan con el mismo período del mes anterior, en nominal y en real
// (descontando el último IPC publicado, pestaña IPC).
const q = $('Limpiar y parsear JSON').first().json;
const c = q.consulta;

const aDia = f => {
  const m = String(f || '').match(/^(\d{2})-(\d{2})-(\d{4})$/);
  return m ? Date.UTC(+m[3], +m[2] - 1, +m[1]) / 86400000 : null;
};
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fmt = n => {
  try { return Number(n).toLocaleString('es-AR', { maximumFractionDigits: 2 }); } catch (e) { return String(n); }
};
const aNumero = v => typeof v === 'number' ? v
  : Number(String(v || '').replace(/[^\d,.-]/g, '').replace(/\./g, '').replace(',', '.')) || 0;

const desde = aDia(c.desde);
const hasta = aDia(c.hasta);
const filas = $('Leer movimientos').all().map(i => i.json).filter(f => f && f.Monto !== undefined && f.Monto !== '');
const coincide = (f, d0, d1) => {
  const dia = aDia(f.Fecha);
  if (dia === null || dia < d0 || dia > d1) return false;
  if (c.tipo !== 'AMBOS' && f.Tipo !== c.tipo) return false;
  if (c.categoria && f['Categoría'] !== c.categoria) return false;
  return true;
};
const dentro = filas.filter(f => coincide(f, desde, hasta));

const sumar = tipo => {
  const t = {};
  dentro.filter(f => f.Tipo === tipo).forEach(f => {
    const m = f.Moneda || 'ARS';
    t[m] = (t[m] || 0) + (Number(f.Monto) || 0);
  });
  return t;
};
const linea = t => Object.keys(t).length
  ? Object.entries(t).map(([m, v]) => '$' + fmt(v) + ' ' + m).join(' · ')
  : '$0';

const gastos = sumar('GASTO');
const ingresos = sumar('INGRESO');
const rango = c.desde === c.hasta ? c.desde : c.desde + ' al ' + c.hasta;

let msg = '📊 <b>Resumen — ' + esc(c.titulo) + '</b>\n📅 ' + rango;
if (c.categoria) msg += '\n🏷️ ' + esc(c.categoria);

if (!dentro.length) {
  msg += '\n\nNo encontré movimientos en ese período.';
} else {
  msg += '\n';
  if (c.tipo !== 'INGRESO') msg += '\n💸 <b>Gastos:</b> ' + linea(gastos);
  if (c.tipo !== 'GASTO') msg += '\n💰 <b>Ingresos:</b> ' + linea(ingresos);
  if (c.tipo === 'AMBOS') {
    const monedas = [...new Set([...Object.keys(gastos), ...Object.keys(ingresos)])];
    msg += '\n⚖️ <b>Balance:</b> ' + monedas
      .map(m => '$' + fmt((ingresos[m] || 0) - (gastos[m] || 0)) + ' ' + m).join(' · ');
  }

  // Top 5 categorías de gasto por moneda
  if (c.tipo !== 'INGRESO' && !c.categoria) {
    Object.keys(gastos).forEach(m => {
      const porCat = {};
      dentro.filter(f => f.Tipo === 'GASTO' && (f.Moneda || 'ARS') === m).forEach(f => {
        const k = f['Categoría'] || 'Otros';
        porCat[k] = (porCat[k] || 0) + (Number(f.Monto) || 0);
      });
      const top = Object.entries(porCat).sort((a, b) => b[1] - a[1]).slice(0, 5);
      msg += '\n\n🏷️ <b>Gastos por categoría (' + m + '):</b>\n' +
        top.map(([k, v]) => '• ' + esc(k) + ': $' + fmt(v)).join('\n');
    });
  }

  // Pesos vs el mismo período del mes anterior, nominal y descontando la inflación del último IPC
  const ipc = $('Leer IPC').all().map(i => i.json).filter(r => r && r.Mes);
  const ultimoIpc = ipc.length ? aNumero(ipc[ipc.length - 1]['Inflación %']) : null;
  const mesAntes = d => {
    const f = new Date(d * 86400000);
    const y = f.getUTCFullYear(), m = f.getUTCMonth() - 1;
    const fin = new Date(Date.UTC(y, m + 1, 0)).getUTCDate();
    return Date.UTC(y, m, Math.min(f.getUTCDate(), fin)) / 86400000;
  };
  if (c.tipo !== 'INGRESO' && gastos.ARS && ultimoIpc !== null && hasta - desde <= 31) {
    const previo = filas
      .filter(f => f.Tipo === 'GASTO' && (f.Moneda || 'ARS') === 'ARS' && coincide(f, mesAntes(desde), mesAntes(hasta)))
      .reduce((s, f) => s + (Number(f.Monto) || 0), 0);
    if (previo > 0) {
      const nominal = gastos.ARS / previo - 1;
      const real = (1 + nominal) / (1 + ultimoIpc / 100) - 1;
      const pct = x => (x >= 0 ? '+' : '') + (x * 100).toFixed(1).replace('.', ',') + '%';
      msg += '\n\n📈 <b>Gastos en pesos vs mismo período del mes anterior:</b> ' + pct(nominal) + ' nominal · ' +
        pct(real) + ' real (IPC ' + String(ultimoIpc).replace('.', ',') + '%)';
    }
  }

  msg += '\n\n🧾 ' + dentro.length + (dentro.length === 1 ? ' movimiento' : ' movimientos');
}

return [{ json: { mensaje: msg, chat_id: q.chat_id } }];

// Arma la respuesta de "¿cuánto tengo?" con la pestaña Saldos (una fila por moneda: ARS, USD, EUR,
// que nunca se suman entre sí) y la pestaña Cripto (saldos de Binance en USD, la escribe cada hora
// el workflow "Finanzas - Saldos cripto Binance"). La cripto se suma solo a los dólares.
const q = $('Limpiar y parsear JSON').first().json;
const filas = $('Leer saldos').all().map(i => i.json).filter(f => f && f.Moneda);
const cripto = $('Leer cripto').all().map(i => i.json).filter(f => f && f.Activo);

const dinero = (n, moneda) => (n < 0 ? '-$' : '$') +
  Math.abs(n).toLocaleString('es-AR', { minimumFractionDigits: Number.isInteger(n) ? 0 : 2, maximumFractionDigits: 2 }) + ' ' + moneda;
const aNumero = v => typeof v === 'number' ? v
  : Number(String(v || '').replace(/[^\d,.-]/g, '').replace(/\./g, '').replace(',', '.')) || 0;
// La hoja Cripto guarda texto con punto decimal ("6457.67"); acepta coma por si se edita a mano.
const aNumeroCripto = v => {
  if (typeof v === 'number') return v;
  let t = String(v || '').trim().replace(/[^\d.,-]/g, '');
  if (t.includes(',')) t = t.replace(/\./g, '').replace(',', '.');
  return Number(t) || 0;
};
// Actualizado puede venir como texto DD-MM-YYYY o como número de serie de fecha de Sheets
const aDia = v => {
  if (typeof v === 'number') return Math.floor(v) - 25569;
  const m = String(v || '').match(/^(\d{2})-(\d{2})-(\d{4})$/);
  return m ? Date.UTC(+m[3], +m[2] - 1, +m[1]) / 86400000 : null;
};
const diaATexto = d => {
  const f = new Date(d * 86400000);
  return String(f.getUTCDate()).padStart(2, '0') + '-' + String(f.getUTCMonth() + 1).padStart(2, '0') + '-' + f.getUTCFullYear();
};

if (!filas.length) {
  return [{ json: { chat_id: q.chat_id, mensaje: '❌ No pude leer la pestaña Saldos. Probá de nuevo en unos minutos.' } }];
}

const ETIQUETAS = { ARS: '🇦🇷 Pesos', USD: '🇺🇸 Dólares', EUR: '🇪🇺 Euros' };
const ORDEN = ['ARS', 'USD', 'EUR'];
const moneda = f => String(f.Moneda).trim().toUpperCase();
const ordenadas = filas.slice().sort((a, b) => {
  const ia = ORDEN.indexOf(moneda(a)), ib = ORDEN.indexOf(moneda(b));
  return (ia === -1 ? 99 : ia) - (ib === -1 ? 99 : ib);
});

let msg = '💳 <b>¿Cuánto tengo?</b>\n\n' + ordenadas
  .map(f => '<b>' + (ETIQUETAS[moneda(f)] || moneda(f)) + ':</b> ' + dinero(aNumero(f.Saldo), moneda(f)))
  .join('\n');

const conValor = cripto.map(f => ({ activo: String(f.Activo).trim(), usd: aNumeroCripto(f['Total USD']) })).filter(c => c.usd > 0);
if (conValor.length) {
  const totalCripto = Math.round(conValor.reduce((s, c) => s + c.usd, 0) * 100) / 100;
  const filaUsd = filas.find(f => moneda(f) === 'USD');
  const usd = filaUsd ? aNumero(filaUsd.Saldo) : 0;
  const top = conValor.sort((a, b) => b.usd - a.usd).slice(0, 3)
    .map(c => c.activo + ' ' + Math.round((c.usd / totalCripto) * 100) + '%').join(' · ');
  msg += '\n<b>🪙 Cripto (Binance):</b> ' + dinero(totalCripto, 'USD') + '\n   ' + top;
  msg += '\n\n💵 <b>Total en dólares (con cripto):</b> ' + dinero(Math.round((usd + totalCripto) * 100) / 100, 'USD');
} else {
  msg += '\n<b>🪙 Cripto (Binance):</b> sin datos por ahora';
}

const dias = filas.map(f => aDia(f.Actualizado)).filter(d => d !== null);
if (dias.length) msg += '\n\n🕒 Última actualización: ' + diaATexto(Math.max(...dias));
const criptoAct = cripto.length ? String(cripto[0].Actualizado || '').trim() : '';
if (criptoAct) msg += '\n🪙 Cripto actualizada: ' + criptoAct;

return [{ json: { chat_id: q.chat_id, mensaje: msg } }];

// Reemplaza el saldo total de una moneda (pestaña Saldos, una fila por moneda) por el que pidió el usuario.
const q = $('Limpiar y parsear JSON').first().json;
const filas = $input.all().map(i => i.json).filter(f => f && f.Moneda);

const dinero = (n, moneda) => (n < 0 ? '-$' : '$') +
  Math.abs(n).toLocaleString('es-AR', { minimumFractionDigits: Number.isInteger(n) ? 0 : 2, maximumFractionDigits: 2 }) + ' ' + moneda;
// El Saldo llega como número; por las dudas acepta texto tipo "781.457,14"
const aNumero = v => typeof v === 'number' ? v
  : Number(String(v || '').replace(/[^\d,.-]/g, '').replace(/\./g, '').replace(',', '.')) || 0;
const NOMBRES = { ARS: 'pesos', USD: 'dólares', EUR: 'euros' };

const moneda = q.moneda;
const fila = filas.find(f => String(f.Moneda).trim().toUpperCase() === moneda);
if (!fila) {
  return [{ json: { actualizar: false, chat_id: q.chat_id, mensaje: filas.length
    ? '⚠️ No hay una fila de ' + moneda + ' en la pestaña Saldos. Agregala a mano y probá de nuevo.'
    : '❌ No pude leer la pestaña Saldos. Probá de nuevo en unos minutos.' } }];
}

const anterior = aNumero(fila.Saldo);
const nuevo = q.monto;
const dif = Math.round((nuevo - anterior) * 100) / 100;

return [{
  json: {
    actualizar: true,
    row_number: fila.row_number,
    saldo_nuevo: nuevo,
    actualizado: $now.setZone('America/Argentina/Cordoba').toFormat('dd-MM-yyyy'),
    chat_id: q.chat_id,
    mensaje: '🔧 <b>Saldo en ' + (NOMBRES[moneda] || moneda) + ' ajustado:</b> ' + dinero(nuevo, moneda) +
      '\n(antes ' + dinero(anterior, moneda) + ', diferencia ' + (dif > 0 ? '+' : '') + dinero(dif, moneda) + ')',
  },
}];

// "¿Cuánto valgo?": todo el patrimonio en dólares (pesos al MEP, euros con EUR/USD de Binance, cripto en USD)
// y la variación contra la foto diaria de hace unos 30 días (pestaña Patrimonio).
const q = $('Limpiar y parsear JSON').first().json;
const saldos = $('Leer saldos (patrimonio)').all().map(i => i.json).filter(f => f && f.Moneda);
const cripto = $('Leer cripto (patrimonio)').all().map(i => i.json).filter(f => f && f.Activo);
const historial = $('Leer historial patrimonio').all().map(i => i.json).filter(f => f && f.Fecha);
const mep = Number($('Dólar MEP (bot)').first().json.venta);
const eurUsd = Number($('EUR/USD (bot)').first().json.price);
if (!(mep > 0) || !(eurUsd > 0)) {
  return [{ json: { chat_id: q.chat_id, mensaje: '❌ No pude obtener la cotización del dólar ahora. Probá de nuevo en unos minutos.' } }];
}

// Saldo llega como número o como texto es-AR ("953.562,87"); la hoja Cripto usa punto decimal ("4990.75")
const aNumero = v => typeof v === 'number' ? v
  : Number(String(v || '').replace(/[^\d,.-]/g, '').replace(/\./g, '').replace(',', '.')) || 0;
const aNumeroCripto = v => {
  if (typeof v === 'number') return v;
  let t = String(v || '').trim().replace(/[^\d.,-]/g, '');
  if (t.includes(',')) t = t.replace(/\./g, '').replace(',', '.');
  return Number(t) || 0;
};
const fmt = (n, d) => Number(n).toLocaleString('es-AR', { minimumFractionDigits: d || 0, maximumFractionDigits: d || 0 });
const saldo = m => { const f = saldos.find(s => String(s.Moneda).trim().toUpperCase() === m); return f ? aNumero(f.Saldo) : 0; };
const aDia = f => { const m = String(f || '').match(/^(\d{2})-(\d{2})-(\d{4})$/); return m ? Date.UTC(+m[3], +m[2] - 1, +m[1]) / 86400000 : null; };

const ars = saldo('ARS'), usd = saldo('USD'), eur = saldo('EUR');
const criptoUsd = cripto.reduce((s, c) => s + aNumeroCripto(c['Total USD']), 0);
const partes = [
  { et: '🇦🇷 Pesos', usd: ars / mep, extra: '$' + fmt(ars) + ' ARS' },
  { et: '🇺🇸 Dólares', usd: usd, extra: '' },
  { et: '🇪🇺 Euros', usd: eur * eurUsd, extra: '€' + fmt(eur) },
  { et: '🪙 Cripto', usd: criptoUsd, extra: '' },
];
const total = partes.reduce((s, p) => s + p.usd, 0);

let msg = '💼 <b>Patrimonio total: US$ ' + fmt(total) + '</b>\n≈ $' + fmt(total * mep) + ' ARS (dólar MEP $' + fmt(mep, 2) + ')\n';
for (const p of partes) {
  msg += '\n' + p.et + ': US$ ' + fmt(p.usd) + ' (' + (total ? Math.round(p.usd / total * 100) : 0) + '%)' + (p.extra ? ' · ' + p.extra : '');
}

const hoyDia = aDia($now.setZone('America/Argentina/Cordoba').toFormat('dd-MM-yyyy'));
const previo = historial
  .map(h => ({ dia: aDia(h.Fecha), total: aNumero(h['Total USD']) }))
  .filter(h => h.dia !== null && h.dia <= hoyDia - 30 && h.total > 0)
  .sort((a, b) => b.dia - a.dia)[0];
if (previo) {
  const dif = total - previo.total;
  msg += '\n\n📈 vs hace ' + (hoyDia - previo.dia) + ' días: ' + (dif >= 0 ? '+' : '-') + 'US$ ' + fmt(Math.abs(dif)) +
    ' (' + (dif >= 0 ? '+' : '') + (dif / previo.total * 100).toFixed(1).replace('.', ',') + '%)';
} else {
  msg += '\n\n<i>📈 La evolución aparece cuando haya fotos diarias de hace más de 30 días.</i>';
}

return [{ json: { chat_id: q.chat_id, mensaje: msg } }];

// "¿Puedo gastar X en Y?": cruza el saldo de esa moneda, lo gastado este mes en la categoría,
// el promedio de los 3 meses anteriores y el presupuesto (si hay). No registra nada.
const q = $('Limpiar y parsear JSON').first().json;
const filas = $('Leer movimientos (permitir)').all().map(i => i.json).filter(f => f && f.Monto !== undefined && f.Monto !== '');
const saldos = $('Leer saldos (permitir)').all().map(i => i.json).filter(f => f && f.Moneda);
const presupuestos = $('Leer presupuestos (permitir)').all().map(i => i.json).filter(f => f && f['Categoría']);

const aNumero = v => typeof v === 'number' ? v
  : Number(String(v || '').replace(/[^\d,.-]/g, '').replace(/\./g, '').replace(',', '.')) || 0;
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const dinero = (n, m) => (n < 0 ? '-$' : '$') + Math.abs(n).toLocaleString('es-AR', { maximumFractionDigits: 2 }) + ' ' + m;
const claveMes = f => { const m = String(f || '').match(/^(\d{2})-(\d{2})-(\d{4})$/); return m ? +m[3] * 12 + (+m[2] - 1) : null; };

const hoy = $now.setZone('America/Argentina/Cordoba');
const mesActual = hoy.year * 12 + (hoy.month - 1);
const porMes = {};
for (const f of filas) {
  if (f.Tipo !== 'GASTO' || String(f.Moneda || 'ARS').toUpperCase() !== q.moneda || f['Categoría'] !== q.categoria) continue;
  const k = claveMes(f.Fecha);
  if (k !== null) porMes[k] = (porMes[k] || 0) + (Number(f.Monto) || 0);
}
const gastadoMes = porMes[mesActual] || 0;
const previos = [1, 2, 3].map(i => porMes[mesActual - i] || 0).filter(v => v > 0);
const promedio = previos.length ? previos.reduce((a, b) => a + b, 0) / previos.length : 0;
const filaSaldo = saldos.find(s => String(s.Moneda).trim().toUpperCase() === q.moneda);
const saldo = filaSaldo ? aNumero(filaSaldo.Saldo) : null;
const pres = presupuestos.find(p => p['Categoría'] === q.categoria && String(p.Moneda || 'ARS').toUpperCase() === q.moneda && aNumero(p['Monto mensual']) > 0);
const tope = pres ? aNumero(pres['Monto mensual']) : 0;
const despues = gastadoMes + q.monto;

let veredicto;
if (saldo !== null && saldo - q.monto < 0) veredicto = '🔴 <b>No te alcanza el saldo</b> en ' + q.moneda + '.';
else if (tope && despues > tope) veredicto = '🔴 <b>Te pasarías del presupuesto</b> por ' + dinero(despues - tope, q.moneda) + '.';
else if (tope && despues > tope * 0.8) veredicto = '🟡 <b>Podés, pero ojo:</b> usarías el ' + Math.round(despues / tope * 100) + '% del presupuesto del mes.';
else if (promedio && despues > promedio * 1.3) veredicto = '🟡 <b>Podés, pero ojo:</b> quedarías ' + Math.round((despues / promedio - 1) * 100) + '% arriba de tu promedio en esta categoría.';
else veredicto = '🟢 <b>Sí, dale.</b> Está dentro de lo normal para vos.';

const lineas = ['🤔 <b>¿' + esc(q.descripcion || 'Este gasto') + ' por ' + dinero(q.monto, q.moneda) + '?</b>', '', veredicto, ''];
if (saldo !== null) lineas.push('💳 Saldo en ' + q.moneda + ': ' + dinero(saldo, q.moneda) + ' → quedaría ' + dinero(saldo - q.monto, q.moneda));
lineas.push('🏷️ ' + esc(q.categoria) + ' este mes: ' + dinero(gastadoMes, q.moneda) + (promedio ? ' (promedio mensual ' + dinero(Math.round(promedio), q.moneda) + ')' : ''));
if (tope) lineas.push('🎯 Presupuesto: ' + dinero(tope, q.moneda) + ' → usarías ' + Math.round(despues / tope * 100) + '%');
lineas.push('', '<i>No registré nada: si lo comprás, contámelo como gasto.</i>');

return [{ json: { chat_id: q.chat_id, mensaje: lineas.join('\n') } }];
